package com.aistock.prediction.verification;
import com.fasterxml.jackson.databind.*;import com.aistock.common.BusinessException;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;
public final class VerificationService {
 private final VerificationRepository repo;private final VerificationMarketClient market;private final VerificationCalculator calculator;private final ObjectMapper mapper;private final Clock clock;private final int hour;private final com.aistock.prediction.marketuse.PredictionMarketUseOwner uses;
 public VerificationService(VerificationRepository repo,VerificationMarketClient market,VerificationCalculator calculator,ObjectMapper mapper,Clock clock,int hour){this(repo,market,calculator,mapper,clock,hour,null);}
 public VerificationService(VerificationRepository repo,VerificationMarketClient market,VerificationCalculator calculator,ObjectMapper mapper,Clock clock,int hour,com.aistock.prediction.marketuse.PredictionMarketUseOwner uses){this.uses=uses;this.repo=repo;this.market=market;this.calculator=calculator;this.mapper=mapper;this.clock=clock;this.hour=hour;}
 public VerificationReceipt verify(UUID prediction,VerificationRequest r){var deadline=clock.instant().plusSeconds(90);var now=ZonedDateTime.now(clock.withZone(ZoneId.of("Asia/Shanghai")));var cutoff=now.getHour()<hour?now.toLocalDate().minusDays(1):now.toLocalDate();if(prediction==null||r==null||r.operationId()==null||r.dueThrough()==null||r.dueThrough().isBefore(LocalDate.of(1990,1,1))||r.dueThrough().isAfter(cutoff)||r.leaseUntil()==null||r.leaseUntil().isAfter(clock.instant().plusSeconds(120)))throw VerificationRepository.error("VERIFICATION_REQUEST_INVALID",HttpStatus.BAD_REQUEST);
  var claim=repo.begin(prediction,r,VerificationEvidence.hash(mapper,List.of(prediction,r,VerificationRecords.RULE)),deadline);if(!claim.execute())return claim.receipt();
  try{budget(deadline);if(!clock.instant().isBefore(r.leaseUntil()))throw VerificationRepository.error("ATTEMPT_EXPIRED",HttpStatus.CONFLICT);var snapshot=claim.snapshot();var origin=LocalDate.parse(snapshot.path("input").path("originDate").asText());if(r.dueThrough().isBefore(origin)||r.dueThrough().isAfter(origin.plusDays(90)))throw VerificationValidator.invalid();var dates=snapshot.path("input").path("targetDates");if(!dates.isArray()||dates.size()!=5)throw VerificationValidator.invalid();if(LocalDate.parse(dates.get(0).asText()).isAfter(r.dueThrough()))return repo.finish(r.operationId(),1,"SKIPPED_NOT_DUE",null);
   try(var scope=uses==null?com.aistock.prediction.marketuse.MarketUseContext.empty():uses.acquire("PREDICTION_VERIFICATION",r.operationId(),1)){
    budget(deadline);
    if(!clock.instant().isBefore(r.leaseUntil()))throw VerificationRepository.error("ATTEMPT_EXPIRED",HttpStatus.CONFLICT);
    var evidence=market.prepare(r,snapshot,deadline);var raw=com.aistock.prediction.marketuse.MarketUseContext.expectedRaw();if(raw!=null&&!raw.equals(evidence.path("rawVersionId").asText()))throw com.aistock.prediction.marketuse.MarketUseClient.invalid();budget(deadline);var parsed=VerificationEvidence.read(mapper,evidence,r,clock);var result=calculator.calculate(snapshot,parsed);return repo.publish(prediction,r,evidence,result,VerificationEvidence.hash(mapper,List.of(evidence,result,VerificationRecords.RULE)),deadline,1);}
  }catch(BusinessException e){return repo.finish(r.operationId(),1,"FAILED",e.code());}catch(Exception e){return repo.finish(r.operationId(),1,"FAILED","VERIFICATION_SOURCE_UNAVAILABLE");}finally{if(uses!=null)uses.notifyCompleted("PREDICTION_VERIFICATION",r.operationId(),1);}
 }
 private void budget(Instant deadline){if(!clock.instant().isBefore(deadline))throw VerificationRepository.error("VERIFICATION_BUDGET_EXCEEDED",HttpStatus.SERVICE_UNAVAILABLE);}
 public VerificationReceipt operation(UUID operation){return repo.operation(operation);}public JsonNode current(UUID prediction){return repo.current(prediction);}
}
